import { OrderDto, PlaceOrderDto } from "./dtos";
import { DomainError, NotFoundError } from "../domain/errors";
import { Order, OrderItem, OrderState } from "../domain/order";
import { OrderRepository, ProductRepository } from "../domain/repositories";

export class OrderService {
  private nextId = 1;

  public constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
  ) {}

  public placeOrder(input: PlaceOrderDto): OrderDto {
    const items = this.combineItems(input.items);
    const products = items.map((item) => {
      const product = this.products.findById(item.productId);
      if (!product) throw new NotFoundError(`Product ${item.productId} was not found`);
      return product;
    });
    // Validate every reservation before modifying any stock.
    for (let index = 0; index < items.length; index += 1) {
      if (products[index].stock < items[index].quantity) {
        throw new DomainError(`Insufficient stock for product ${items[index].productId}`);
      }
    }
    for (let index = 0; index < items.length; index += 1) {
      products[index].reserve(items[index].quantity);
      this.products.save(products[index]);
    }
    const order = new Order(`order-${this.nextId++}`, items);
    this.orders.save(order);
    return this.toDto(order);
  }

  public getOrder(id: string): OrderDto {
    return this.toDto(this.requireOrder(id));
  }

  public listOrders(state?: OrderState): OrderDto[] {
    return this.orders.listByState(state).map((order) => this.toDto(order));
  }

  public advanceOrder(id: string, target: "paid" | "packed" | "shipped" | "delivered"): OrderDto {
    const order = this.requireOrder(id);
    order.advanceTo(target);
    this.orders.save(order);
    return this.toDto(order);
  }

  public cancelOrder(id: string): OrderDto {
    const order = this.requireOrder(id);
    order.cancel();
    for (const item of order.items) {
      const product = this.products.findById(item.productId);
      if (!product) throw new NotFoundError(`Product ${item.productId} was not found`);
      product.release(item.quantity);
      this.products.save(product);
    }
    this.orders.save(order);
    return this.toDto(order);
  }

  private combineItems(items: PlaceOrderDto["items"]): OrderItem[] {
    if (!Array.isArray(items) || items.length === 0) throw new DomainError("An order requires at least one item");
    const quantities = new Map<string, number>();
    for (const item of items) {
      if (!item || !item.productId || !Number.isInteger(item.quantity) || item.quantity <= 0) {
        throw new DomainError("Each order item needs a product id and positive integer quantity");
      }
      quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
    }
    return [...quantities].map(([productId, quantity]) => ({ productId, quantity }));
  }

  private requireOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new NotFoundError(`Order ${id} was not found`);
    return order;
  }

  private toDto(order: Order): OrderDto {
    return { id: order.id, state: order.state, items: order.items.map((item) => ({ ...item })) };
  }
}

